import{_ as r,o,c as s,a2 as e}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"收藏夹","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/favorites.md","filePath":"zh-CN/user-guide/settings/favorites.md","lastUpdated":1788164125000}'),a={name:"zh-CN/user-guide/settings/favorites.md"};function n(i,t,l,g,d,c){return o(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="收藏夹" tabindex="-1">收藏夹 <a class="header-anchor" href="#收藏夹" aria-label="Permalink to &quot;收藏夹&quot;">​</a></h1><p>收藏夹用于将你最高频使用的文件夹、文件、脚本或网页 URL 固定下来，赋予专属的自定义名称与最高检索优先级。设置页面路径为<strong>设置 → 收藏夹</strong>。</p><h2 id="_1-添加收藏项目" tabindex="-1">1. 添加收藏项目 <a class="header-anchor" href="#_1-添加收藏项目" aria-label="Permalink to &quot;1. 添加收藏项目&quot;">​</a></h2><p>在页面上方的添加表单中：</p><ul><li><strong>显示名称</strong>：自定义名称（可选）。若留空且目标为本地路径，系统会自动使用目标文件或文件夹的文件名作为默认名称。</li><li><strong>目标路径</strong>：支持输入本地文件/目录的绝对路径，或以 <code>http://</code> / <code>https://</code> 开头的完整网页网址。</li><li><strong>浏览选择</strong>：点击<strong>浏览文件夹</strong>或<strong>浏览文件</strong>按钮可直接调用原生文件选择器，免去手动输入路径的繁琐。</li><li><strong>添加</strong>：填入有效路径后点击<strong>添加</strong>按钮即可将该项存入收藏列表。</li></ul><h2 id="_2-列表管理与拖拽排序" tabindex="-1">2. 列表管理与拖拽排序 <a class="header-anchor" href="#_2-列表管理与拖拽排序" aria-label="Permalink to &quot;2. 列表管理与拖拽排序&quot;">​</a></h2><p>下方列表集中展示所有已添加的收藏项，支持细致的排序与维护：</p><ul><li><strong>六点拖拽手柄排序</strong>：每一行左侧均配有六点拖拽手柄，你可以按住手柄直接上下拖动调整条目顺序，亦可点击右侧的<strong>向上移动</strong> / <strong>向下移动</strong>按钮微调。这里的排列顺序直接决定了该收藏项在搜索结果与快速导航菜单中的先后次序。</li><li><strong>就地编辑</strong>：点击编辑后，当前行会直接变成编辑器，可在该行保存或取消，不会复用上方的添加表单。</li><li><strong>删除此项</strong>：从收藏夹中安全移除该条目。</li><li><strong>清空列表</strong>：列表有内容时，可以使用列表标题右侧的按钮一次移除所有收藏项；列表为空时该按钮会隐藏。</li></ul><p>你也可以在搜索结果的动作菜单中，将单个已存在的文件或文件夹直接添加到收藏夹。Lertaro 会弹出对话框让你填写显示名称；如果相同路径已经收藏，该动作不会显示。</p><h2 id="_3-搜索召回与视觉呈现" tabindex="-1">3. 搜索召回与视觉呈现 <a class="header-anchor" href="#_3-搜索召回与视觉呈现" aria-label="Permalink to &quot;3. 搜索召回与视觉呈现&quot;">​</a></h2><ul><li><strong>专属星标徽标（★）</strong>：在快速窗口或主搜索窗口中检索到收藏项时，结果旁会显示醒目的 <strong>★</strong> 星标徽标。</li><li><strong>自定义别名搜索</strong>：你可以为复杂的路径起一个简短好记的显示名称（例如将 <code>D:\\Workspace\\2026\\Q1\\Financial\\Summary.xlsx</code> 命名为 <code>财务总表</code>）。在搜索框中输入 <code>cwzb</code> 即可通过拼音别名秒级召回该文件。</li><li><strong>多端聚合呈现</strong>：所有收藏项会自动同步呈现在<a href="./../hotkeys.html#3-快速导航鼠标触发"><strong>鼠标快速导航</strong></a>菜单与<a href="./quick-panel.html#4-插件标签plugin-tabs"><strong>快速面板</strong></a>的“收藏夹”标签中，点击即可秒开。</li></ul>',11)])])}const _=r(a,[["render",n]]);export{u as __pageData,_ as default};
